mapper.select:
SELECT fi.item_id AS itemId, fi.item_name AS itemName, fi.item_type AS itemType, fi.charge_standard AS chargeStandard, fi.charge_unit AS chargeUnit, fi.charge_cycle AS chargeCycle, fi.status AS status, fi.create_by AS createBy, fi.create_time AS createTime, fi.update_by AS updateBy, fi.update_time AS updateTime, fi.remark AS remark FROM community_fee_item fi
AND fi.item_name LIKE CONCAT('%', #{q.itemName}, '%')
AND fi.item_type = #{q.itemType}
AND fi.charge_cycle = #{q.chargeCycle}
AND fi.status = #{q.status}
ORDER BY fi.create_time DESC, fi.item_id DESC
